#include <iostream>
#include <string>
#include <stdexcept>

int main() {
    std::string s1{"happy"};
    std::string s2{" birthday"};
    std::string s3;

    std::cout << std::boolalpha;
    std::cout << "s3.empty(): " << s3.empty() << "\n";

    s3 = s1;
    s1 += s2;
    s1 += " to you";
    std::cout << "s1: " << s1 << "\n";

    std::string sub1 = s1.substr(0, 14);
    std::string sub2 = s1.substr(15);
    std::cout << "sub1: " << sub1 << "\n";
    std::cout << "sub2: " << sub2 << "\n";

    s1[0] = 'H';
    s1[6] = 'B';
    std::cout << "Capitalized s1: " << s1 << "\n";

    try {
        s1.at(100) = 'X';
    } catch (const std::out_of_range& ex) {
        std::cout << "Caught exception: " << ex.what() << "\n";
    }

    return 0;
}

#include <iostream>

class Coordinate {
private:
    int x{0};
    int y{0};

public:
    Coordinate(int xVal, int yVal) : x{xVal}, y{yVal} {}

    // Member function binary operator<
    // Invoked as: lhs.operator<(rhs)
    bool operator<(const Coordinate& rhs) const {
        if (x != rhs.x) {
            return x < rhs.x;
        }
        return y < rhs.y;
    }

    // Non-member binary operator== declared as friend
    friend bool operator==(const Coordinate& lhs, const Coordinate& rhs) {
        return (lhs.x == rhs.x) && (lhs.y == rhs.y);
    }

    void print() const {
        std::cout << "(" << x << ", " << y << ")";
    }
};

int main() {
    Coordinate p1{2, 5};
    Coordinate p2{3, 1};
    Coordinate p3{2, 5};

    std::cout << std::boolalpha;

    // Calls p1.operator<(p2)
    std::cout << "p1 < p2: " << (p1 < p2) << "\n";

    // Calls operator==(p1, p3)
    std::cout << "p1 == p3: " << (p1 == p3) << "\n";

    return 0;
}
